<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{FeeRepository,SettingsRepository,StudentRepository};use App\Services\FeeService;use App\Support\Flash;
final class FeesController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function students():StudentRepository{return new StudentRepository($this->app->database());}private function fees():FeeRepository{return new FeeRepository($this->app->database());}private function denied():?Response{return can('fees.view')?null:Response::html('Forbidden',403);}private function month(string$m):bool{return(bool)preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$m);}
public function collect(Request$r):Response{if($x=$this->denied())return$x;$q=trim((string)$r->query('student_query',''));$month=(string)$r->query('month',date('Y-m'));$studentId=(int)$r->query('student_id',0);$class=(int)$r->query('class',0);$onlyDue=(bool)$r->query('only_due',0);$selected=$studentId?$this->students()->find($studentId,$this->i()):null;$invoice=null;$items=[];$payments=[];$pending=[];$preview=null;if(!$selected&&$q)$selected=$this->students()->byRegistration($q,$this->i());if($selected&&$this->month($month)){$invoice=$this->fees()->invoice((int)$selected['id'],$month);if($invoice){$items=$this->fees()->items((int)$invoice['id']);$payments=$this->fees()->payments((int)$invoice['id']);}$pending=$this->fees()->pendingInvoices((int)$selected['id'],$month);$preview=(!$invoice||((float)$invoice['paid_amount']<=0&&!$invoice['voided_at']&&!$payments))?(new FeeService($this->fees(),$this->students()))->preview($selected,$this->i(),$month):null;}$raw=$this->app->database()->query('SELECT payment_methods_json FROM fee_settings WHERE institute_id=:i',['i'=>$this->i()])->fetchColumn();$methods=json_decode((string)$raw,true);if(!is_array($methods)||!$methods)$methods=['Cash','Bank','Online Transfer','Cheque','JazzCash','Easypaisa','Other'];return$this->renderPage('fees-collect',['studentResults'=>$this->students()->paginate($this->i(),$q,$class?:null,0,$onlyDue),'selectedStudent'=>$selected,'selectedMonth'=>$month,'invoice'=>$invoice,'invoiceItems'=>$items,'payments'=>$payments,'paymentMethods'=>$methods,'query'=>$q,'browseStudents'=>(bool)$r->query('browse',0),'selectedClass'=>$class,'onlyDue'=>$onlyDue,'classes'=>(new \App\Repositories\AcademicRepository($this->app->database()))->classes($this->i()),'pendingOtherMonths'=>$pending,'preview'=>$preview]);}
public function createInvoice(Request$r):Response{if($x=$this->denied())return$x;$reg=trim((string)$r->input('registration'));$month=(string)$r->input('month');$student=$this->students()->byRegistration($reg,$this->i());if(!$student||!$this->month($month))return Response::html('Invalid student or fee month',422);(new FeeService($this->fees(),$this->students()))->ensureInvoice($student,$this->i(),$month,(int)user()['id']);Flash::add('success','Fee invoice ready.');return Response::redirect(url('/admin/fees/collect?student_query='.rawurlencode($reg).'&month='.$month));}
public function payment(Request$r):Response{if($x=$this->denied())return$x;$reg=trim((string)$r->input('registration'));$month=(string)$r->input('month');$amount=$r->input('payment_amount');$method=(string)$r->input('payment_method');$configured=$this->app->database()->query('SELECT payment_methods_json FROM fee_settings WHERE institute_id=:i',['i'=>$this->i()])->fetchColumn();$methods=json_decode((string)$configured,true);if(!is_array($methods)||!$methods)$methods=['Cash','Bank','Bank Transfer','Online Transfer','Cheque','JazzCash','Easypaisa','Card','Other'];$student=$this->students()->byRegistration($reg,$this->i());if(!$student||!$this->month($month)||!is_numeric($amount)||!in_array($method,$methods,true))return Response::html('Invalid payment details',422);try{$svc=new FeeService($this->fees(),$this->students());$labels=(array)$r->input('item_label',[]);$amounts=(array)$r->input('item_amount',[]);if($labels){$existing=$this->fees()->invoice((int)$student['id'],$month);$paidSoFar=$existing?(float)$existing['paid_amount']:0.0;if($existing&&$existing['voided_at'])throw new \InvalidArgumentException('This invoice is voided.');if($paidSoFar<=0||can('*')){$lines=[];foreach($labels as$k=>$label){$v=$amounts[$k]??0;if(!is_numeric($v))throw new \InvalidArgumentException('Enter a number for every fee particular.');if((float)$v<0)throw new \InvalidArgumentException('Fee amounts cannot be negative.');$lines[]=['particular'=>(string)$label,'amount'=>(float)$v];}$disc=$r->input('discount_amount',0);$fine=$r->input('fine_amount',0);$prevIn=$r->input('previous_balance');if(!is_numeric($disc)||!is_numeric($fine)||($prevIn!==null&&$prevIn!==''&&!is_numeric($prevIn)))throw new \InvalidArgumentException('Discount, fine and previous balance must be numbers.');if((float)$fine<0||(float)$disc<0||($prevIn!==null&&$prevIn!==''&&(float)$prevIn<0))throw new \InvalidArgumentException('Fine, discount and previous balance cannot be negative.');$mode=(string)$r->input('discount_mode','amount');if(!in_array($mode,['amount','percent'],true))throw new \InvalidArgumentException('Choose a discount in amount or percent.');if($mode==='percent'){if((float)$disc>100)throw new \InvalidArgumentException('A percentage discount cannot be more than 100%.');$disc=round(array_sum(array_column($lines,'amount'))*(float)$disc/100,2);}$sub=array_sum(array_column($lines,'amount'))+(float)$fine;$prev=($prevIn!==null&&$prevIn!=='')?(float)$prevIn:($existing?(float)$existing['previous_balance']:$this->fees()->outstandingBefore((int)$student['id'],$month));$expected=max(0,$sub-min($sub,(float)$disc)+$prev);if($expected+0.001<$paidSoFar)throw new \InvalidArgumentException('The new total ('.number_format($expected,2).') cannot be less than the '.number_format($paidSoFar,2).' already paid.');$due=$expected-$paidSoFar;if((float)$amount<=0||(float)$amount>$due+0.001)throw new \InvalidArgumentException('Deposit must be greater than zero and not more than the balance of '.number_format(max(0,$due),2).'.');$inv=$svc->ensureInvoice($student,$this->i(),$month,(int)user()['id']);$change=$svc->adjustInvoice((int)$inv['id'],$lines,(float)$disc,(float)$fine,($prevIn!==null&&$prevIn!=='')?(float)$prevIn:null);if($existing&&json_encode($change['before']['total_amount'])!==json_encode(number_format($change['after']['total_amount'],2,'.','')))(new \App\Repositories\PakistanErpRepository($this->app->database()))->audit($this->i(),(int)user()['id'],'fee.invoice_adjusted','fee_invoice',(int)$inv['id'],$change);}}$id=$svc->collect($student,$this->i(),$month,(float)$amount,$method,trim((string)$r->input('reference'))?:null,(int)user()['id'],(string)$r->input('payment_date','')?:null);$date=(string)$r->input('payment_date','');if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)&&$date<=date('Y-m-d')&&$date!==date('Y-m-d'))$this->app->database()->query('UPDATE fee_payments SET payment_date=:d WHERE id=:id',['d'=>$date,'id'=>$id]);$remarks=trim((string)$r->input('remarks',''));if($remarks!=='')$this->app->database()->query('UPDATE fee_payments SET remarks=:r WHERE id=:id',['r'=>mb_substr($remarks,0,255),'id'=>$id]);}catch(\InvalidArgumentException$e){$this->app->session()->flash('_errors',['payment_amount'=>[$e->getMessage()]]);Flash::add('error',$e->getMessage());return Response::redirect(url('/admin/fees/collect?student_id='.(int)$student['id'].'&month='.$month));}$smsSkipped=\App\Services\Sms\SmsAutomation::$lastSkipped;Flash::add($smsSkipped?'warning':'success','Fee payment recorded.'.($smsSkipped?' The fee-received SMS was NOT sent — '.implode('; ',array_slice($smsSkipped,0,2)).'. Fix the number or template, then use "Send SMS" on this receipt.':''));return Response::redirect(url('/admin/fees/receipt/'.$id));}
public function receipt(Request$r):Response{if($x=$this->denied())return$x;$id=(int)$r->route('id');if(!$id){$f=['q'=>trim((string)$r->query('q','')),'month'=>(string)$r->query('month',''),'from'=>(string)$r->query('from',''),'to'=>(string)$r->query('to',''),'method'=>(string)$r->query('method',''),'reversed'=>(string)$r->query('reversed',''),'student_id'=>(int)$r->query('student_id',0)];if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$f['month']))$f['month']='';foreach(['from','to']as$k)if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$f[$k]))$f[$k]='';if(!in_array($f['reversed'],['','only','all'],true))$f['reversed']='';$filtered=$f['q']!==''||$f['month']||$f['from']||$f['to']||$f['method']||$f['reversed']||$f['student_id'];if(!$filtered){$f['from']=date('Y-m-d',strtotime('-30 days'));}return$this->renderPage('fees-paid-slip',['slips'=>$this->fees()->paidSlips($this->i(),$f),'filters'=>$f,'methods'=>$this->fees()->paymentMethodsUsed($this->i()),'defaultView'=>!$filtered]);}$receipt=$this->fees()->receipt($id,$this->i());if(!$receipt)return Response::html('Receipt not found',404);
$sms=$this->app->database()->query("SELECT status,phone_number,sent_at,created_at FROM sms_messages WHERE institute_id=:i AND dedupe_key=:k ORDER BY id DESC LIMIT 1",['i'=>$this->i(),'k'=>'payment:'.$id])->fetch()?:null;
return$this->renderPage('fees-receipt',['receipt'=>$receipt,'items'=>$this->fees()->items((int)$receipt['fee_invoice_id']),'paymentSms'=>$sms,'paymentSmsOn'=>(new \App\Services\Sms\SmsAutomation($this->app->database()))->paymentSmsEnabled($this->i())]);}
/** "Send SMS" on a receipt whose fee-received SMS never went out (e.g. no number at the time). */
public function sendReceiptSms(Request$r):Response{if($x=$this->denied())return$x;$id=(int)$r->route('id');$receipt=$this->fees()->receipt($id,$this->i());if(!$receipt)return Response::html('Receipt not found',404);$back=url('/admin/fees/receipt/'.$id);
if(!empty($receipt['reversed_at'])){Flash::add('error','This payment was reversed, so no SMS is sent for it.');return Response::redirect($back);}
$existing=$this->app->database()->query("SELECT status FROM sms_messages WHERE institute_id=:i AND dedupe_key=:k AND status NOT IN ('failed','cancelled') LIMIT 1",['i'=>$this->i(),'k'=>'payment:'.$id])->fetchColumn();
if($existing){Flash::add('info','The fee-received SMS for this receipt is already '.($existing==='sent'?'sent':'queued').'.');return Response::redirect($back);}
$auto=new \App\Services\Sms\SmsAutomation($this->app->database());if(!$auto->paymentSmsEnabled($this->i())){Flash::add('error','The Payment Confirmation SMS is switched off in SMS Center → Automations.');return Response::redirect($back);}
$made=$auto->paymentReceived($id);$skipped=\App\Services\Sms\SmsAutomation::$lastSkipped;
Flash::add($made?'success':'error',$made?'Fee-received SMS queued; the gateway phone will send it shortly.':'SMS not sent — '.($skipped?implode('; ',array_slice($skipped,0,2)):'it could not be queued').'.');return Response::redirect($back);}
/** Fee Defaulters filters from the query string, validated (shared by the page, CSV and PDF). */
public static function defaulterFilters(Request$r):array{
$f=['q'=>trim((string)$r->query('search','')),'month'=>trim((string)$r->query('month','')),'class'=>(int)$r->query('class',0),'state'=>(string)$r->query('state',''),'minimum'=>max(0,(float)$r->query('minimum',0)),'sort'=>(string)$r->query('sort','due'),'include_unbilled'=>(bool)$r->query('unbilled',0)];
if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$f['month']))$f['month']='';if(!in_array($f['state'],['','overdue','partial','unpaid','unbilled'],true))$f['state']='';if(!in_array($f['sort'],['due','oldest','name','class'],true))$f['sort']='due';if(!$f['month'])$f['include_unbilled']=false;
return$f;}
public function defaulters(Request$r):Response{if($x=$this->denied())return$x;
$f=self::defaulterFilters($r);
$rows=$this->fees()->defaulters($this->i(),$f);
if((string)$r->query('export')==='csv'){$out=fopen('php://temp','w+');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Student','Registration','Class','Guardian','Phone','Months due','Overdue','Total due','Last payment']);foreach($rows as$x)fputcsv($out,[$x['student_name'],$x['registration_no'],$x['class_name'],$x['guardian'],$x['phone'],implode(' | ',array_map(static fn($m)=>$m['month'].' '.number_format($m['remaining'],2).(!empty($m['not_billed'])?' (not billed)':''),$x['months'])),number_format($x['overdue'],2,'.',''),number_format($x['due'],2,'.',''),$x['last_payment']]);rewind($out);$csv=stream_get_contents($out);fclose($out);return new Response((string)$csv,200,['Content-Type'=>'text/csv; charset=UTF-8','Content-Disposition'=>'attachment; filename="fee-defaulters-'.($f['month']?:date('Y-m-d')).'.csv"']);}
return$this->renderPage('fees-defaulters',['defaulters'=>$rows,'filters'=>$f,'classes'=>(new \App\Repositories\AcademicRepository($this->app->database()))->classes($this->i())]);}
public function report(Request$r):Response{if($x=$this->denied())return$x;return$this->reportPage($r,false);}
public function deleteIndex(Request$r):Response{if($x=$this->denied())return$x;return$this->reportPage($r,true);}
private function reportPage(Request$r,bool$deletion):Response{$month=trim((string)$r->query('month',''));$status=trim((string)$r->query('status',''));$search=trim((string)$r->query('search',''));$rows=$this->fees()->report($this->i(),$month,$status,$search);$totals=['billed'=>0.0,'paid'=>0.0,'remaining'=>0.0];foreach($rows as$row){$totals['billed']+=(float)$row['total_amount'];$totals['paid']+=(float)$row['paid_amount'];$totals['remaining']+=(float)$row['remaining_amount'];}return$this->renderPage($deletion?'fees-delete':'fees-report',['invoices'=>$rows,'totals'=>$totals,'selectedMonth'=>$month,'selectedStatus'=>$status,'search'=>$search,'deletionMode'=>$deletion]);}
public function deleteInvoice(Request$r):Response{if($x=$this->denied())return$x;if((string)$r->input('confirm')!=='delete')return Response::html('Deletion confirmation is required.',422);if(!$this->fees()->deleteInvoice((int)$r->route('id'),$this->i())){Flash::add('error','Invoices with payment history cannot be deleted. Reverse payments and void the invoice instead.');return Response::redirect(url('/admin/fees/delete'));}Flash::add('success','Unused fee invoice deleted.');return Response::redirect(url('/admin/fees/delete'));}
public function reversePayment(Request$r):Response{if($x=$this->denied())return$x;$id=(int)$r->route('id');$reason=trim((string)$r->input('reason'));if($reason===''||!$this->fees()->reversePayment($id,$this->i(),(int)user()['id'],$reason)){Flash::add('error','Payment was not found or is already reversed.');}else{(new \App\Repositories\PakistanErpRepository($this->app->database()))->audit($this->i(),(int)user()['id'],'fee.payment_reversed','fee_payment',$id,['reason'=>$reason]);Flash::add('success','Payment reversed with an audit reason.');}$to=(string)$r->input('return','');return Response::redirect(str_starts_with($to,'/admin/')?url($to):url('/admin/fees/report'));}
public function voidInvoice(Request$r):Response{if($x=$this->denied())return$x;$id=(int)$r->route('id');$reason=trim((string)$r->input('reason'));if($reason===''||!$this->fees()->voidInvoice($id,$this->i(),(int)user()['id'],$reason)){Flash::add('error','Only unpaid, active invoices can be voided.');}else{(new \App\Repositories\PakistanErpRepository($this->app->database()))->audit($this->i(),(int)user()['id'],'fee.invoice_voided','fee_invoice',$id,['reason'=>$reason]);Flash::add('success','Invoice voided.');}return Response::redirect(url('/admin/fees/report'));}

private function methods():array{$configured=$this->app->database()->query('SELECT payment_methods_json FROM fee_settings WHERE institute_id=:i',['i'=>$this->i()])->fetchColumn();$methods=json_decode((string)$configured,true);return is_array($methods)&&$methods?$methods:['Cash','Bank','Bank Transfer','Online Transfer','Cheque','JazzCash','Easypaisa','Card','Other'];}
private function collectUrl(array$p):string{return url('/admin/fees/collect?student_id='.(int)$p['student_id'].'&month='.rawurlencode((string)$p['fee_month']));}
public function editPayment(Request$r):Response{if(!can('*'))return Response::html('Only an administrator can edit posted fee payments.',403);$p=$this->fees()->payment((int)$r->route('id'),$this->i());if(!$p)return Response::html('Payment not found',404);return$this->renderPage('fee-payment-edit',['payment'=>$p,'methods'=>$this->methods(),'return'=>(string)$r->query('return','')]);}
public function updatePayment(Request$r):Response{if(!can('*'))return Response::html('Only an administrator can edit posted fee payments.',403);$id=(int)$r->route('id');$p=$this->fees()->payment($id,$this->i());if(!$p)return Response::html('Payment not found',404);$date=(string)$r->input('payment_date');$amount=$r->input('amount');$method=(string)$r->input('payment_method');$methods=$this->methods();if(!in_array($p['payment_method'],$methods,true))$methods[]=$p['payment_method'];$to=(string)$r->input('return','');$back=str_starts_with($to,'/admin/')?url($to):$this->collectUrl($p);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!is_numeric($amount)||!in_array($method,$methods,true)){Flash::add('error','Enter a valid date, amount and payment method.');return Response::redirect(url('/admin/fees/payments/'.$id.'/edit'));}try{$before=$this->fees()->editPayment($id,$this->i(),$date,(float)$amount,$method,trim((string)$r->input('reference'))?:null,trim((string)$r->input('remarks'))?:null);}catch(\DomainException$e){Flash::add('error',$e->getMessage());return Response::redirect(url('/admin/fees/payments/'.$id.'/edit'));}(new \App\Repositories\PakistanErpRepository($this->app->database()))->audit($this->i(),(int)user()['id'],'fee.payment_edited','fee_payment',$id,['before'=>['date'=>$before['payment_date'],'amount'=>$before['amount'],'method'=>$before['payment_method'],'reference'=>$before['reference']],'after'=>['date'=>$date,'amount'=>(float)$amount,'method'=>$method]]);Flash::add('success','Fee payment updated and the invoice balance recalculated.');return Response::redirect($back);}
}
